# Same-book equivalents share only after an explicit sense review. Captions remain word-specific.
ALIASES={'angrily':'angry','port':'harbour','ventilation':'ventilate','sympathetically':'sympathetic','fortunate':'luck','record-holder':'champion','successful':'succeed'}
# Do not override a deliberate Book 1 reuse with a same-book alias.
for k in list(ALIASES):
 if k in REUSE:ALIASES.pop(k)

def main():
 words=json.loads((OUT/'source-words.json').read_text())
 names={w['word'] for w in words}
 for mapping in [REUSE,HINTS,DIAGRAMS,SCENES,ALIASES]:
  extra=set(mapping)-names
  if extra:raise ValueError(f'Unknown word keys: {extra}')
 for w in words:
  key=w['word'];w['filename']='academy-b2-'+hashlib.sha256(key.encode()).hexdigest()[:16]+'.png'
  if key in HINTS:w.update(kind='native_hint',hint=HINTS[key])
  elif key in REUSE:
   source=B1[REUSE[key]]
   while source['kind']=='shared_illustration':source=B1[source['same_as']]
   assert source['kind']!='native_hint',key
   w.update(kind='shared_book_illustration',source_book_id=1,source_word=REUSE[key],source_filename=source['filename'],review_reason='Explicit sense-reviewed visual reuse; no case-folding or automatic spelling match.')
   if source.get('presentation'):w['presentation']=source['presentation']
   if REUSE[key]==key and source.get('caption'):w['caption']=source['caption']
   # A source caption is reusable only when it remains grammatical for this exact term.
  elif key in ALIASES:w.update(kind='shared_illustration',same_as=ALIASES[key],review_reason='Explicit same-book semantic equivalent.')
  elif key in DIAGRAMS:w.update(kind='native_diagram',diagram=DIAGRAMS[key],presentation='diagram')
  else:
   w.update(kind='ai_illustration',scene=SCENES.get(key,f"Clearly depict {key!r} ONLY in this textbook sense: {w['meaning']}. Use a recognizable object or a minimal human situation; avoid unrelated common meanings."))
  if key in CAPTIONS:w['caption']=CAPTIONS[key]
  if w['kind']=='ai_illustration' and key in CAPTIONS:w['presentation']='scene'
 jobs=[];pics=[w for w in words if w['kind']=='ai_illustration']
 for i in range(0,len(pics),4):jobs.append({'id':f'academy-b2-{i//4+1:03d}','cells':[dict(index=j,word=w['word'],meaning=w['meaning'],filename=w['filename'],scene=w['scene']) for j,w in enumerate(pics[i:i+4])]})
 p={'format_version':1,'book_id':2,'word_count':len(words),'width':320,'height':320,'format':'PNG','max_bytes':200000,'style_reference':'Design/2026-10-11-word-illustration-pilot/sources/academy-pilot-02.png','words':words,'jobs':jobs}
 dest=OUT/'plan.json'
 if dest.exists():raise SystemExit('Plan already exists; do not overwrite generation progress')
 dest.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
 from collections import Counter
 print(dict(Counter(w['kind'] for w in words)),len(jobs),'atlases')
 print('Generic prompts:',[w['word'] for w in pics if w['word'] not in SCENES])
if __name__=='__main__':main()
